pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 root, bool useOracle, bool payRoyalties) public {
        vm.assume(feeRate <= 5000);
        c.initialize(address(0), address(0), vBase, vNft, changeFee, feeRate, root, useOracle, payRoyalties);
        bool reverted = false;
        try c.initialize(address(0), address(0), vBase, vNft, changeFee, feeRate, root, useOracle, payRoyalties) {} catch { reverted = true; }
        assertTrue(reverted);
    }
}
